   160	async function validateVenue(
   161	  name: string | null,
   162	  city: string | null,
   163	  lat: number | null,
   164	  lng: number | null,
   165	  address: string | null,
   166	  venueId: string | null = null
   167	): Promise<VenueValidationResult> {
   168	  // Check valid name
   169	  if (!isValidVenueName(name)) {
   170	    return { isValid: false, reason: 'invalid_name', qualityScore: 0, verifiedInEvents: false, eventCount: 0, confidence_score: 0 };
   171	  }
   172	
   173	  // Check against blacklist
   174	  const normalized = name.toLowerCase().trim();
   175	  if (VENUE_BLACKLIST.some(bad => normalized === bad || normalized.includes(bad))) {
   176	    return { isValid: false, reason: 'blacklisted', qualityScore: 0, verifiedInEvents: false, eventCount: 0, confidence_score: 0 };
   177	  }
   178	
   179	  // Check if venue already exists in verified venues table
   180	  const verified = await isVerifiedVenue(name);
   181	  if (verified) {
   182	    return { isValid: false, reason: 'already_verified', qualityScore: 100, verifiedInEvents: true, eventCount: 0, confidence_score: 100 };
   183	  }
   184	
   185	  // Check if venue already exists in candidates (any source)
   186	  const { data: existing } = await supabase
   187	    .from('discovery_venue_candidates')
   188	    .select('id')
   189	    .eq('name', name)
   190	    .limit(1);
   191	
   192	  if (existing && existing.length > 0) {
   193	    return { isValid: false, reason: 'already_candidate', qualityScore: 0, verifiedInEvents: false, eventCount: 0, confidence_score: 0 };
   194	  }
   195	
   196	  // Check if venue appears in events table (CRITICAL validation)
   197	  const eventCheck = await isVenueInEvents(name, venueId);
   198	  if (eventCheck.found) {
   199	    console.log(`[validation] ✅ Venue "${name}" verified in events table (${eventCheck.eventCount} events)`);
   200	  }
   201	
   202	  // Calculate quality score
   203	  const quality = scoreVenueQuality(name, city, lat, lng, address);
   204	
   205	  // Minimum quality threshold
   206	  if (quality.score < 30) {
   207	    return { isValid: false, reason: 'low_quality', qualityScore: quality.score, verifiedInEvents: eventCheck.found, eventCount: eventCheck.eventCount, confidence_score: quality.score };
   208	  }
   209	
   210	  // Calculate confidence score: quality score + bonuses/penalties
   211	  let confidence_score = quality.score;
   212	  if (eventCheck.found) {
   213	    confidence_score += 1; // +1 if venue found in events
   214	  }
   215	  if (!city || !isStockholm(city)) {
   216	    confidence_score -= 1; // -1 if city is missing or outside Stockholm
   217	  }
   218	
   219	  // Skip venues with low confidence (quality < 30 AND not in events)
   220	  if (confidence_score < 30) {
   221	    return { isValid: false, reason: 'low_confidence', qualityScore: quality.score, verifiedInEvents: eventCheck.found, eventCount: eventCheck.eventCount, confidence_score };
   222	  }
   223	
   224	  return { isValid: true, qualityScore: quality.score, verifiedInEvents: eventCheck.found, eventCount: eventCheck.eventCount, confidence_score };
   225	}
